import type { GearItem } from '@/types/database'
import { GEAR_BRANDS, ALL_CATEGORY_KEYWORDS, detectBrand, detectCategory } from '@/constants/gear'

export interface CsvRow {
  [key: string]: string
}

export interface ParsedGearItem {
  name: string
  brand?: string
  weight_grams: number
  category: string
  quantity: number
  worn: boolean
  consumable: boolean
  price?: number
  description?: string
  notes?: string
}

export interface CsvParseResult {
  success: boolean
  data: ParsedGearItem[]
  errors: string[]
  warnings: string[]
}

// Common CSV column mappings for LighterPack exports with intelligent detection
const COLUMN_MAPPINGS = {
  name: ['name', 'item name', 'item', 'gear name', 'product'],
  brand: ['brand', 'manufacturer', 'make'],
  weight: ['weight', 'weight (g)', 'weight (grams)', 'weight_grams', 'wt', 'oz', 'grams'],
  category: ['category', 'type', 'gear type', 'class'],
  quantity: ['quantity', 'qty', 'count', 'amount'],
  worn: ['worn', 'worn weight', 'is worn'],
  consumable: ['consumable', 'consumables', 'is consumable'],
  price: ['price', 'cost', 'price (usd)', 'amount', '$'],
  description: ['description', 'desc', 'details', 'notes'],
  notes: ['notes', 'comments', 'remarks', 'additional notes'],
}


/**
 * Parse CSV text into structured gear data
 */
export function parseCsv(csvText: string): CsvParseResult {
  const result: CsvParseResult = {
    success: true,
    data: [],
    errors: [],
    warnings: []
  }

  try {
    // Simple CSV parser - handles quoted fields and commas
    const lines = csvText.trim().split('\n')
    if (lines.length < 2) {
      result.success = false
      result.errors.push('CSV must have at least a header row and one data row')
      return result
    }

    // Parse header row
    const headers = parseCsvLine(lines[0]).map(h => h.toLowerCase().trim())

    // Parse all rows for intelligent analysis
    const allParsedRows = lines.map(line => parseCsvLine(line))

    // Create column mapping with intelligent detection
    const columnMap = mapColumns(headers, allParsedRows)

    if (columnMap.name === undefined) {
      result.success = false
      result.errors.push('No name/item column found. Required columns: name, weight')
      return result
    }

    if (columnMap.weight === undefined) {
      result.success = false
      result.errors.push('No weight column found. Required columns: name, weight')
      return result
    }

    // Parse data rows
    for (let i = 1; i < lines.length; i++) {
      const line = lines[i].trim()
      if (!line) continue // Skip empty lines

      try {
        const values = parseCsvLine(line)
        const gearItem = parseGearRow(values, columnMap, headers)

        if (gearItem) {
          result.data.push(gearItem)
        }
      } catch (error) {
        result.errors.push(`Row ${i + 1}: ${error instanceof Error ? error.message : 'Invalid data'}`)
      }
    }

    // Add summary warnings
    if (result.data.length === 0) {
      result.errors.push('No valid gear items found in CSV')
      result.success = false
    } else if (result.errors.length > 0) {
      result.warnings.push(`Successfully parsed ${result.data.length} items with ${result.errors.length} errors`)
    }

  } catch (error) {
    result.success = false
    result.errors.push(`Failed to parse CSV: ${error instanceof Error ? error.message : 'Unknown error'}`)
  }

  return result
}

/**
 * Parse a single CSV line handling quoted fields
 */
function parseCsvLine(line: string): string[] {
  const result: string[] = []
  let current = ''
  let inQuotes = false

  for (let i = 0; i < line.length; i++) {
    const char = line[i]
    const nextChar = line[i + 1]

    if (char === '"') {
      if (inQuotes && nextChar === '"') {
        // Escaped quote
        current += '"'
        i++ // Skip next quote
      } else {
        // Toggle quote state
        inQuotes = !inQuotes
      }
    } else if (char === ',' && !inQuotes) {
      // End of field
      result.push(current.trim())
      current = ''
    } else {
      current += char
    }
  }

  result.push(current.trim())
  return result
}

/**
 * Analyze content to detect column usage patterns
 */
function analyzeColumnUsage(rows: string[][], headers: string[]): Record<string, any> {
  const analysis: Record<string, any> = {}

  // Sample first 10 rows for analysis
  const sampleRows = rows.slice(0, Math.min(10, rows.length))

  headers.forEach((header, index) => {
    const headerLower = header.toLowerCase().trim()
    const values = sampleRows.map(row => row[index]?.toLowerCase().trim()).filter(Boolean)

    if (values.length === 0) return

    analysis[header] = {
      index,
      containsCategories: 0,
      containsBrands: 0,
      containsDescriptions: 0,
      avgLength: 0,
      sampleValues: values.slice(0, 3)
    }

    values.forEach(value => {
      // Check for category keywords
      const categoryMatches = ALL_CATEGORY_KEYWORDS.filter(keyword => 
        value.includes(keyword.toLowerCase())
      ).length
      if (categoryMatches > 0) analysis[header].containsCategories++

      // Check for brand keywords  
      const brandMatches = GEAR_BRANDS.filter(keyword =>
        value.includes(keyword.toLowerCase())
      ).length
      if (brandMatches > 0) analysis[header].containsBrands++

      // Check if it looks like a description (longer text, contains common words)
      if (value.length > 20 || value.includes(' ') && !categoryMatches && !brandMatches) {
        analysis[header].containsDescriptions++
      }
    })

    analysis[header].avgLength = values.reduce((sum, val) => sum + val.length, 0) / values.length
  })

  return analysis
}

/**
 * Map CSV headers to our data structure with intelligent detection
 */
function mapColumns(headers: string[], allRows?: string[][]): Record<string, number | undefined> {
  const map: Record<string, number | undefined> = {}

  // First pass: standard mapping
  for (const [field, variants] of Object.entries(COLUMN_MAPPINGS)) {
    for (let i = 0; i < headers.length; i++) {
      const header = headers[i].toLowerCase().trim()
      if (variants.some(variant => {
        const normalizedVariant = variant.toLowerCase().trim()
        return header === normalizedVariant || header.includes(normalizedVariant)
      })) {
        map[field] = i
        break
      }
    }
  }

  // Second pass: intelligent content analysis for ambiguous cases
  if (allRows && allRows.length > 1) {
    const analysis = analyzeColumnUsage(allRows.slice(1), headers) // Skip header row

    // If we found a description column but no category column, 
    // check if description is being used for categories
    if (map.description !== undefined && map.category === undefined) {
      const descHeader = headers[map.description]
      const descAnalysis = analysis[descHeader]

      // Only remap if MOST entries are clearly categories and few are brands/descriptions
      if (descAnalysis && 
          descAnalysis.containsCategories > descAnalysis.containsBrands + descAnalysis.containsDescriptions &&
          descAnalysis.containsCategories >= allRows.length * 0.6) {
        // Description field is being used primarily for categories
        map.category = map.description
        delete map.description
      }
    }

    // If we found description but no brand, check if description contains brand info
    if (map.description !== undefined && map.brand === undefined) {
      const descHeader = headers[map.description]
      const descAnalysis = analysis[descHeader]

      if (descAnalysis && descAnalysis.containsBrands > 0 && descAnalysis.avgLength < 30) {
        // Description field might contain brand info
        // Keep as description but extract brand info during parsing
      }
    }

    // Look for name column alternatives - sometimes users put detailed names in description
    if (map.name !== undefined) {
      const nameHeader = headers[map.name]
      const nameAnalysis = analysis[nameHeader]

      // If name column is very short and we have a description with longer entries
      if (nameAnalysis && nameAnalysis.avgLength < 10 && map.description !== undefined) {
        const descHeader = headers[map.description]
        const descAnalysis = analysis[descHeader]

        if (descAnalysis && descAnalysis.avgLength > nameAnalysis.avgLength * 2) {
          // Consider swapping or using description as extended name info
        }
      }
    }
  }

  return map
}

/**
 * Parse a single gear item row
 */
function parseGearRow(
  values: string[], 
  columnMap: Record<string, number | undefined>,
  headers: string[]
): ParsedGearItem | null {
  const getValue = (field: string): string => {
    const index = columnMap[field]
    return index !== undefined ? values[index]?.trim() || '' : ''
  }

  // Required fields
  const name = getValue('name')
  if (!name) {
    throw new Error('Item name is required')
  }

  const weightStr = getValue('weight')
  if (!weightStr) {
    throw new Error('Weight is required')
  }

  // Parse weight - handle different units
  const weight_grams = parseWeight(weightStr)
  if (weight_grams <= 0) {
    throw new Error(`Invalid weight: ${weightStr}`)
  }

  // Optional fields with defaults
  let brand = getValue('brand') || undefined
  let category = getValue('category') || 'Other'
  const quantity = Math.max(1, parseInt(getValue('quantity')) || 1)

  // Try to extract brand from description if no explicit brand column
  if (!brand && getValue('description')) {
    brand = detectBrand(getValue('description'))
  }

  // Use intelligent category detection if category is generic
  if (category === 'Other' || !category) {
    const detectedCategory = detectCategory(`${name} ${getValue('description') || ''}`)
    if (detectedCategory !== 'Other') {
      category = detectedCategory
    }
  }

  // Boolean fields
  const worn = parseBoolean(getValue('worn'))
  const consumable = parseBoolean(getValue('consumable'))

  // Numeric fields
  const priceStr = getValue('price')
  const price = priceStr ? parsePrice(priceStr) : undefined

  const description = getValue('description') || undefined
  const notes = getValue('notes') || undefined

  return {
    name,
    brand,
    weight_grams,
    category,
    quantity,
    worn,
    consumable,
    price,
    description,
    notes
  }
}

/**
 * Parse weight string and convert to grams
 */
function parseWeight(weightStr: string): number {
  const cleaned = weightStr.toLowerCase().replace(/[^\d.,oz\s]/g, '').trim()

  // Extract number
  const numberMatch = cleaned.match(/([\d.,]+)/)
  if (!numberMatch) return 0

  const value = parseFloat(numberMatch[1].replace(',', ''))
  if (isNaN(value)) return 0

  // Check unit
  if (cleaned.includes('oz')) {
    return Math.round(value * 28.3495) // Convert oz to grams
  }

  // Default to grams
  return Math.round(value)
}

/**
 * Parse price string
 */
function parsePrice(priceStr: string): number | undefined {
  const cleaned = priceStr.replace(/[^\d.,]/g, '')
  const value = parseFloat(cleaned)
  return isNaN(value) ? undefined : value
}

/**
 * Parse boolean string
 */
function parseBoolean(boolStr: string): boolean {
  const cleaned = boolStr.toLowerCase().trim()
  return ['true', '1', 'yes', 'y', 'worn', 'consumable'].includes(cleaned)
}

/**
 * Validate parsed gear items before import
 */
export function validateGearItems(items: ParsedGearItem[]): { valid: ParsedGearItem[], invalid: Array<{ item: ParsedGearItem, errors: string[] }> } {
  const valid: ParsedGearItem[] = []
  const invalid: Array<{ item: ParsedGearItem, errors: string[] }> = []

  for (const item of items) {
    const errors: string[] = []

    if (!item.name || item.name.length < 2) {
      errors.push('Name must be at least 2 characters')
    }

    if (item.weight_grams <= 0) {
      errors.push('Weight must be greater than 0')
    }

    if (item.weight_grams > 50000) { // 50kg seems reasonable max
      errors.push('Weight seems unusually high (>50kg)')
    }

    if (item.quantity < 1) {
      errors.push('Quantity must be at least 1')
    }

    if (item.price !== undefined && item.price < 0) {
      errors.push('Price cannot be negative')
    }

    if (errors.length === 0) {
      valid.push(item)
    } else {
      invalid.push({ item, errors })
    }
  }

  return { valid, invalid }
}

export interface DuplicateCheckResult {
  unique: ParsedGearItem[]
  duplicates: Array<{ item: ParsedGearItem, duplicateOf: number }>
  warnings: string[]
}

/**
 * Check for duplicate items within the parsed list
 * Considers items duplicate if they have same name (case-insensitive) and similar weight (±5g)
 */
export function checkForDuplicates(items: ParsedGearItem[]): DuplicateCheckResult {
  const unique: ParsedGearItem[] = []
  const duplicates: Array<{ item: ParsedGearItem, duplicateOf: number }> = []
  const warnings: string[] = []

  for (let i = 0; i < items.length; i++) {
    const currentItem = items[i]
    let isDuplicate = false

    // Check against all unique items so far
    for (let j = 0; j < unique.length; j++) {
      const existingItem = unique[j]

      // Check if names match (case-insensitive)
      const namesMatch = currentItem.name.toLowerCase().trim() === existingItem.name.toLowerCase().trim()

      // Check if weights are similar (within 5g)
      const weightDiff = Math.abs(currentItem.weight_grams - existingItem.weight_grams)
      const weightsMatch = weightDiff <= 5

      // Check if brands match (if both have brands)
      const brandsMatch = !currentItem.brand || !existingItem.brand || 
        currentItem.brand.toLowerCase().trim() === existingItem.brand.toLowerCase().trim()

      if (namesMatch && weightsMatch && brandsMatch) {
        duplicates.push({ item: currentItem, duplicateOf: j })
        isDuplicate = true
        break
      }
    }

    if (!isDuplicate) {
      unique.push(currentItem)
    }
  }

  if (duplicates.length > 0) {
    warnings.push(`Found ${duplicates.length} potential duplicate${duplicates.length === 1 ? '' : 's'} (similar name/weight/brand)`)
  }

  return { unique, duplicates, warnings }
}

